      "parent": "A45D2/00\\",
      "ja": "頭皮に垂直に髪を巻き付けるものまたはヘアーカーラー，すなわち，スティープカーラー（Ａ４５Ｄ６／１４，Ａ４５Ｄ６／１６が優先；加熱または乾燥装置付のものＡ４５Ｄ２／３６；ヘアーカーラーまたは髪をウェーブする器具が外部にあり，それと関連して用いられる加熱装置Ａ４５Ｄ４／０２）",
      "en": "Hair winders or hair curlers for use substantially perpendicular to the scalp, i.e. steep-curlers (A45D 6/14, A45D 6/16 take precedence; with incorporated heating or drying means A45D 2/36; heating devices designed for use external to and in connection with, hair curlers or hair wavers A45D 4/02)",
